// ─── Global loader ────────────────────────────────────────────────

/// Global loading indicator: Material 3 morphing circular indicator
/// with the cat SVG logo centered inside.
class GlobalLoader extends StatelessWidget {
  const GlobalLoader({
    super.key,
    this.message,
    this.size = 240,
  });

  final String? message;
  final double size;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;

    return Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Morphing loading circle using native Material 3 CircularProgressIndicator
          // wrapped around the cat SVG logo.
          SizedBox(
            width: size,
            height: size,
            child: Stack(
              alignment: Alignment.center,
              children: [
                // Material 3 morphing loading ring
                SizedBox(
                  width: size,
                  height: size,
                  child: CircularProgressIndicator(
                    strokeWidth: 3.5,
                    color: scheme.primary,
                  ),
                ),
                // Cat logo in the center
                Padding(
                  padding: const EdgeInsets.all(28),
                  child: SvgPicture.string(
                    _kCatBodySvg,
                    fit: BoxFit.contain,
                  ),
                ),
              ],
            ),
          ),
          if (message != null) ...[
            const SizedBox(height: 24),
            Text(
              message!,
              style: theme.textTheme.bodyMedium?.copyWith(
                color: scheme.onSurfaceVariant,
              ),
            ),
          ],
        ],
      ),
    );
  }
}
